UAsset myAsset = new UAsset("C:\\plwp_6aam_a0.uasset", EngineVersion.VER_UE4_18);
Export exp = myAsset["Default__plwp_6aam_a0_C"]; // Export contains all fields contained within UAssetGUI's "Export Information"
// to manipulate data under "Export Data," you generally need to cast it to a child type // NormalExport contains most all "normal" data, i.e. standard tagged properties
if (exp is NormalExport normalExport)
{ for (int i = 0; i < normalExport.Data.Count; i++) { PropertyData prop = normalExport.Data[i]; Console.WriteLine(prop.Name.ToString() + ": " + prop.PropertyType.ToString()); // you can access prop.Value for many types, but for other types, you can cast to a child type and access other fields if (prop is FloatPropertyData floatProp) floatProp.Value = 60; // change all floats to = 60 // ArrayPropertyData.Value is a PropertyData[] array, entries referenced by index // StructPropertyData.Value is a List<PropertyData>, or you can index StructPropertyData directly if (prop is ArrayPropertyData arrProp) { for (int j = 0; j < arrProp.Value.Length; j++) { PropertyData prop2 = arrProp.Value[j]; Console.WriteLine(prop2.Name.ToString() + ": " + prop2.PropertyType.ToString()); // etc. // note that arrays and structs can contain arrays and structs too... } } if (prop is StructPropertyData structProp) { for (int j = 0; j < structProp.Value.Count; j++) { PropertyData prop2 = structProp.Value[j]; Console.WriteLine(prop2.Name.ToString() + ": " + prop2.PropertyType.ToString()); // etc. // note that arrays and structs can contain arrays and structs too... } // or: // PropertyData prop2 = structProp["PropertyNameHere"]; } }
} // DataTableExport is a NormalExport, but also contains entries in DataTables
if (exp is DataTableExport dtExport)
{ // dtExport.Data exists, but it typically only contains struct type information // to access other entries, use: List<StructPropertyData> entries = dtExport.Table.Data; // etc.
} // RawExport is an export that failed to parse for some reason, but you can still access and modify its binary data
if (exp is RawExport rawExport)
{ byte[] rawData = rawExport.Data; // etc.
} // see other examples for more advanced export types!

