UAsset myAsset = new UAsset("C:\\my_asset.uasset", EngineVersion.VER_UE4_18); // all StructExport exports can contain blueprint bytecode, let's pretend Export 1 is a StructExport
StructExport myStructExport = (StructExport)myAsset.Exports[0]; KismetExpression[] bytecode = myStructExport.ScriptBytecode;
if (bytecode != null) // bytecode may fail to parse, in which case it will be null and stored raw in ScriptBytecodeRaw
{ // KismetExpression has many child classes, one child class for each type of instruction // as with PropertyData, you can access .RawValue for many instruction types, but you'll need to cast for other kinds of instructions to access specific fields foreach (KismetExpression instruction in bytecode) { Console.WriteLine(instruction.Token.ToString() + ": " + instruction.RawValue.ToString()); }
}
